import itertools
import networkx as nx

def solve_small(n):
    max_n2 = 0
    # For larger n, we cannot iterate over all graphs.
    # But we can try some common types:
    # 1. Star graph
    # 2. Complete bipartite graphs K_{a, b}
    # 3. Random graphs
    # 4. Graphs with a few high-degree nodes

    # Star graph
    max_n2 = (n-1)*(n-2)//2

    # Complete bipartite K_{a, b}
    for a in range(1, n):
        b = n - a
        n2 = a*(a-1)//2 + b*(b-1)//2
        if n2 > max_n2:
            max_n2 = n2

    # Let's try some random graphs
    import random
    for _ in range(10000):
        # Randomly choose an edge probability
        p = random.random()
        G = nx.fast_gnp_random_graph(n, p)
        n2 = 0
        for u, v in itertools.combinations(range(n), 2):
            if not G.has_edge(u, v):
                if any(G.has_edge(u, w) and G.has_edge(v, w) for w in range(n)):
                    n2 += 1
        if n2 > max_n2:
            max_n2 = n2

    return max_n2

for n in range(3, 11):
    print(f"n={n}: {solve_small(n)}")
